mapper.select:
select id,
src_app,
todo_title,
todo_content,
send_time,
create_time,
view_state,
process_state,
todo_type,
relate_link,
urge_flag
from user_todo

    target_user = #{vo.userId}

        and initiator_id = #{vo.userId}



            and process_state = #{vo.processState}




            and process_state = #{vo.processState}



        and (todo_title like concat('%', #{vo.keyword}, '%')
        or todo_content like concat('%', #{vo.keyword}, '%'))


        and todo_type = #{vo.todoType}


        and view_state = #{vo.viewState}


        and send_time >= #{vo.sendTimeStart}


        and #{vo.sendTimeEnd} >= send_time


        and src_app in

            #{a}





        order by urge_flag desc, create_time asc


        order by send_time desc

select td.id, td.src_id, td.src_app, td.todo_title, td.todo_content, td.target_user, td.send_time, td.process_state, td.view_state, td.todo_type, td.relate_link, td.origin_json, td.create_time, td.update_time from user_todo td join user_org uo on td.target_user = uo.user_id
uo.org_id in
#{orgId}
and td.process_state = #{vo.processState}
and td.view_state = #{vo.viewState}
and (td.todo_title like concat('%', #{vo.keyword}, '%') or td.todo_content like concat('%', #{vo.keyword}, '%'))
and td.todo_type = #{vo.todoType}
and td.src_app in
#{a}
and td.send_time >= #{vo.sendTimeStart}
and #{vo.sendTimeEnd} >= td.send_time
order by td.send_time desc

select distinct td.src_app from user_todo td join user_org uo on td.target_user = uo.user_id where uo.org_id in
#{orgId}
and td.src_app is not null and td.src_app != '' order by td.src_app
